/** Actual private title-only widgets for every Source role; no public world acceptance implied. */
@EventBusSubscriber(modid="vandorlabs",value=Dist.CLIENT)
public final class ScreenScreenChecks {
 private static final Map<ScreenFamily,NativeScreenBlock> BLOCKS=new EnumMap<>(ScreenFamily.class);private static BlockEntityType<NativeScreenEntity> TYPE;private static final List<ScreenSettingsPayload> EDITS=new ArrayList<>();private static NativeScreenScreen screen;private static int stage,ticks,checks,frames,initialPlayback,initialLayout;private static String capture;private static boolean captured;private static java.util.concurrent.CompletableFuture<Void> reload;
 private static boolean enabled(){return "true".equals(System.getenv("VANDOR_SCREEN_EDITOR_CHECK"));}
 @EventBusSubscriber(modid="vandorlabs",bus=EventBusSubscriber.Bus.MOD,value=Dist.CLIENT)public static final class Registration {@SubscribeEvent public static void register(net.neoforged.neoforge.registries.RegisterEvent event){if(!enabled())return;event.register(Registries.BLOCK,h->{for(var family:ScreenFamily.values()){var block=NativeScreenBlock.create(family,BlockBehaviour.Properties.of(),()->TYPE);BLOCKS.put(family,block);h.register(ResourceLocation.fromNamespaceAndPath("vandorlabs","screen_editor_fixture_"+family.ordinal()),block);}});event.register(Registries.BLOCK_ENTITY_TYPE,h->{TYPE=BlockEntityType.Builder.<NativeScreenEntity>of((p,s)->new NativeScreenEntity(TYPE,p,s,((NativeScreenBlock)s.getBlock()).family(),NativeScreenCatalog.INSTANCE),BLOCKS.values().toArray(net.minecraft.world.level.block.Block[]::new)).build(null);h.register(ResourceLocation.fromNamespaceAndPath("vandorlabs","screen_editor_fixture"),TYPE);});}}
 private static void need(boolean value,String message){checks++;if(!value)throw new AssertionError("Screen editor stage="+stage+": "+message);}
 private static void open(Minecraft mc,ScreenFamily family){open(mc,family,null);}
 private static void open(Minecraft mc,ScreenFamily family,net.minecraft.nbt.CompoundTag saved){var tile=new NativeScreenEntity(TYPE,BlockPos.ZERO,BLOCKS.get(family).defaultBlockState(),family,NativeScreenCatalog.INSTANCE);if(saved!=null)tile.loadWithComponents(saved,RegistryAccess.EMPTY);initialPlayback=tile.screenSettings().scalar().displayMode;initialLayout=tile.screenSettings().surfaceLayout();screen=new NativeScreenScreen(new NativeScreenMenu(null,49,tile),new Inventory(null),Component.literal("Programmable "+family.name()),EDITS::add);screen.init(mc,mc.getWindow().getGuiScaledWidth(),mc.getWindow().getGuiScaledHeight());}
 private static void click(int id,int mouse){var b=screen.button(id);need(b!=null&&b.active,"button "+id);need(screen.mouseClicked(b.getX()+b.getWidth()/2D,b.getY()+10,mouse),"click "+id);}
 private static void widgets(Minecraft mc){var pair=NativeScreenCatalog.INSTANCE.options().get(0);for(boolean framed:new boolean[]{false,true}){var saved=new net.minecraft.nbt.CompoundTag();saved.putString(com.vandorlabs.persistence.SaveSchema.Screen.SELECTED,framed?pair.framed():pair.bare());saved.putBoolean(com.vandorlabs.persistence.SaveSchema.Screen.FRAMED,!framed);open(mc,ScreenFamily.SCREEN,saved);screen.applyDisplay();need(((NativeScreenDisplayEdit)EDITS.get(EDITS.size()-1).edit()).framed()==(pair.hasPair()?framed:NativeScreenCatalog.INSTANCE.legacyFramed(pair.bare())),"Source canonical artwork determines initial framed choice");}for(var family:ScreenFamily.values()){open(mc,family);need(screen.activePicker()!=null&&screen.button(91)!=null==family.secondary,"role tabs "+family);int count=EDITS.size();click(102,1);need(((NativeScreenDisplayEdit)EDITS.get(count).edit()).playback()==Math.floorMod(initialPlayback-1,3),"reverse playback "+family);click(32,1);need(((NativeScreenLayoutEdit)EDITS.get(EDITS.size()-1).edit()).layout()==Math.floorMod(initialLayout-1,3),"reverse layout "+family);click(111,0);click(112,0);need(screen.page()==5,"rows page "+family);for(int i=0;i<family.standaloneControlRows(0);i++)click(590,0);need(!screen.button(590).active&&screen.rowLabels().size()==family.standaloneControlRows(0),"standalone capacity "+family);screen.rowLabels().get(0).setValue("Long Control Name");screen.rowChannelFields().get(0).setValue("31, 32");click(700,1);need(((NativeScreenRowEdit)EDITS.get(EDITS.size()-1).edit()).rows().get(0).pulse(),"Source reverse kind Toggle to Pulse");click(700,1);need(((NativeScreenRowEdit)EDITS.get(EDITS.size()-1).edit()).rows().get(0).slider(),"reverse row type "+family);need(((NativeScreenRowEdit)EDITS.get(EDITS.size()-1).edit()).rows().get(0).label().length()<=11&&mc.font.width(((NativeScreenRowEdit)EDITS.get(EDITS.size()-1).edit()).rows().get(0).label())<=50,"slider label character and pixel limit on type transition");click(800,1);for(int wrap=0;wrap<4;wrap++)click(800,1);need(((NativeScreenRowEdit)EDITS.get(EDITS.size()-1).edit()).rows().get(0).min()==13,"Source low slider wraps within1..High-2");click(820,1);need(((NativeScreenRowEdit)EDITS.get(EDITS.size()-1).edit()).rows().get(0).max()==15,"Source high slider stays withinLow+2..15");click(580,0);click(93,0);click(3006,1);need(((NativeScreenFrameEdit)EDITS.get(EDITS.size()-1).edit()).frames().displayFit,"frame fit "+family);click(94,0);screen.channelField().setValue("31,");int before=EDITS.size();need(!screen.applyDisplay()&&EDITS.size()==before,"invalid channel draft refused");click(0,1);need(screen.channelField().getValue().equals("31,"),"invalid draft survives activation transition");screen.channelField().setValue("31, 32");need(screen.applyDisplay(),"corrected channel draft");click(654,0);need(screen.activePicker()!=null,"state artwork picker");click(581,0);need(screen.page()==4&&screen.transmission()!=null,"inline transmission shared widget");}
 open(mc,ScreenFamily.SCREEN);var picker=screen.activePicker();picker.searchField().setValue("a");picker.searchField().setFocused(true);need(screen.keyPressed(69,0,0),"query captures key");int before=picker.scroll();need(screen.mouseScrolled(screen.panel().listX+5,picker.top()+5,0,-1)&&picker.scroll()>before,"picker wheel");int bottom=picker.top()+picker.visible()*22-1;need(screen.mouseClicked(screen.panel().listX+screen.panel().listWidth+2,bottom,0),"scrollbar press");int end=picker.scroll();need(screen.mouseDragged(screen.panel().listX+screen.panel().listWidth+2,picker.top(),0,0,-100)&&picker.scroll()<end,"scrollbar drag");screen.mouseReleased(0,0,0);click(92,0);click(90,0);need(screen.activePicker().searchField().getValue().equals("a"),"tab retains picker query");}
 private static void capture(String name){capture=name;captured=false;frames=0;}
 @SubscribeEvent public static void tick(ClientTickEvent.Post event){if(!enabled()||stage==9)return;var mc=Minecraft.getInstance();if(mc.screen instanceof net.minecraft.client.gui.screens.AccessibilityOnboardingScreen intro){intro.onClose();return;}need(++ticks<2200,"title timeout");if(ticks<80||mc.getOverlay()!=null||!(mc.screen instanceof TitleScreen))return;need(mc.level==null&&mc.getSingleplayerServer()==null,"title-only boundary");if(stage==0){mc.getWindow().setWindowed(1280,720);mc.options.guiScale().set(2);mc.resizeDisplay();stage=1;}else if(stage==1){if(mc.getWindow().getGuiScaledWidth()<600)return;widgets(mc);capture("screen-editor-artwork.png");stage=2;}else if(stage==2&&captured){click(111,0);click(112,0);click(590,0);capture("screen-editor-rows.png");stage=3;}else if(stage==3&&captured){click(580,0);click(93,0);capture("screen-editor-frame.png");stage=4;}else if(stage==4&&captured){click(94,0);capture("screen-editor-redstone.png");stage=5;}else if(stage==5&&captured){screen.channelField().setValue("31,");screen.init(mc,400,260);for(var widget:screen.transmission().controls())need(widget.getX()>=screen.panel().left&&widget.getX()+widget.getWidth()<=screen.panel().left+screen.panel().width&&widget.getY()+widget.getHeight()<screen.panel().doneY,"small-screen transmission bounds");for(int id:new int[]{0,650,651,652,653,654}){var widget=screen.button(id);need(widget.getY()+widget.getHeight()<screen.panel().doneY,"small-screen activation bounds");}need(screen.channelField().getValue().equals("31,"),"resize retains invalid channel draft");click(93,0);for(int id:new int[]{3000,3003,3004,3005,3006,3007,3008}){var widget=screen.button(id);need(widget.getY()+widget.getHeight()<screen.panel().doneY,"small-screen frame bounds");}click(90,0);for(int id:new int[]{101,102,103,32,110,111,112,113}){var widget=screen.button(id);need(widget.getY()+widget.getHeight()<screen.panel().doneY,"small-screen artwork bounds");}click(111,0);click(112,0);for(int i=1;i<8;i++)click(590,0);need(screen.rowLabels().size()<8,"small-screen rows bounded viewport");screen.mouseScrolled(screen.panel().left+40,screen.panel().top+100,0,-3);click(580,0);click(94,0);reload=mc.reloadResourcePacks();stage=6;}else if(stage==6&&reload.isDone()){reload.join();need(screen.channelField().getValue().equals("31,"),"reload retains draft");capture("screen-editor-reloaded.png");stage=7;}else if(stage==7&&captured){need(EDITS.stream().filter(p->p.edit() instanceof NativeScreenDisplayEdit).allMatch(p->{var e=(NativeScreenDisplayEdit)p.edit();return NativeScreenCatalog.INSTANCE.validScreen(e.screen())&&NativeScreenCatalog.INSTANCE.validInput(e.input())&&NativeScreenCatalog.INSTANCE.validInput(e.secondary());}),"all selector commands canonicalize saved legacy artwork names");need(EDITS.stream().allMatch(p->p.window()==49&&p.pos().equals(BlockPos.ZERO)),"exact owner/window for every draft");System.out.println("[vandorlabs][screen-editor] title PASS checks="+checks+" commands="+EDITS.size()+" roles=7");stage=9;mc.stop();}}
 @SubscribeEvent public static void draw(ScreenEvent.Render.Post event){if(!enabled()||screen==null||!(event.getScreen() instanceof TitleScreen)||Minecraft.getInstance().getOverlay()!=null)return;var g=event.getGuiGraphics();g.flush();g.pose().pushPose();try{g.pose().translate(0,0,300);g.fill(0,0,Minecraft.getInstance().getWindow().getGuiScaledWidth(),Minecraft.getInstance().getWindow().getGuiScaledHeight(),0xFF101012);screen.render(g,0,0,0);g.flush();}finally{g.pose().popPose();}}
 @SubscribeEvent public static void frame(RenderFrameEvent.Post event){if(!enabled()||capture==null||++frames<6)return;String name=capture;capture=null;var mc=Minecraft.getInstance();Screenshot.grab(mc.gameDirectory,name,mc.getMainRenderTarget(),ignored->captured=true);}
}
